package net.officefloor.hq.app.claim;

import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Move the selected claims to one person together, in list order (people in list order, each
 *  person's claims newest first), each by exactly the rules of moving one claim ({@link ClaimReassign}); a
 *  selected claim already that person's is re-listed as their newest. A claim that cannot be moved is left as
 *  it is and counted as refused. */
public class BulkReassignClaims {
    public void reassign(@PathVariable("sheetId") String sheetId, @RequestBody BulkReassignRequest request,
            ServerHttpConnection connection, ClaimRepository repository, PeriodRepository periods,
            SettingsRepository settings, PersonRepository people, Audit audit, Rollup rollup,
            Out<BulkReassignResult> result) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        Set<Long> selected = new LinkedHashSet<>();
        if (request != null && request.claimIds() != null) {
            for (Long cid : request.claimIds()) {
                if (cid != null) selected.add(cid);
            }
        }
        if (selected.isEmpty()) {
            throw new BadRequestException("select at least one claim");
        }
        if (request.personId() == null) {
            throw new BadRequestException("choose the person to move the claims to");
        }
        List<Claim> found = repository.inListOrder(id, selected);
        int refused = selected.size() - found.size();
        int reassigned = 0;
        for (Claim c : found) {
            try {
                ClaimReassign.apply(id, c.id(), request.personId(), true, by, repository, periods, settings, people, audit, rollup);
                reassigned++;
            } catch (BadRequestException e) {
                refused++;
            }
        }
        result.set(new BulkReassignResult(reassigned, refused));
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;

/** The bulk reassign: the ids of the selected claims and the person on the sheet they move to. */
public record BulkReassignRequest(List<Long> claimIds, Long personId) {
}
package net.officefloor.hq.app.claim;

/** How many of the selected claims were moved and how many were refused. */
public record BulkReassignResult(int reassigned, int refused) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithBulkReassign {
    public void respond(@Val BulkReassignResult result, ObjectResponse<BulkReassignResult> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;

/** A steward re-dates an OPEN or PENDING claim: its due-by may not be in a closed period, nor the new date after its
 *  person's retirement. Its due-by stays as it was fixed and a figure its statement bound stays bound, so its period
 *  (the one containing its due-by) and its number stay as they are. Every check is made before anything is written,
 *  so a refusal writes nothing to the store or the audit. */
final class ClaimRedate {
    private ClaimRedate() {
    }

    static Claim apply(String id, long cid, String newDate, String by, ClaimRepository repository,
            PeriodRepository periods, SettingsRepository settings, PersonRepository people, Audit audit, Rollup rollup)
            throws BadRequestException {
        if (settings.archived(id)) {
            throw new BadRequestException("the sheet is archived");
        }
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
            throw new BadRequestException("only a steward can re-date a claim");
        }
        if (!found.open()) {
            throw new BadRequestException("a " + found.status() + " claim cannot be re-dated");
        }
        String raw = newDate == null ? "" : newDate.trim();
        if (raw.isEmpty()) {
            throw new BadRequestException("give the claim's new date");
        }
        LocalDate date;
        try {
            date = LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new BadRequestException("the new date must be yyyy-mm-dd");
        }
        LocalDate old = LocalDate.parse(found.date());
        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
        people.claimAllowed(id, found.personId(), date);
        Rollup.Snapshot before = rollup.take(id);
        if (!repository.redate(id, cid, date)) {
            throw new BadRequestException("a " + found.status() + " claim cannot be re-dated");
        }
        String number = found.number();
        audit.record("CLAIM_REDATED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
                + " amount=" + found.amount() + " date=" + date + Claim.auditNumber(number)
                + " old=" + old + " new=" + date);
        rollup.record(id, by, before);
        return repository.find(id, cid);
    }
}
# Move the selected claims to one person together: each is moved in list order (people in the order they
# were added, each person's claims newest first) by the rules of moving one claim; every other is left as it
# is. Answers how many were moved and how many refused.
